def fixture() -> str:
    return base64.b64decode(FIXTURE_B64).decode("utf-8")


def added_lines(diff: str, positions: dict[str, dict[int, int]] | None = None) -> dict[str, dict[int, str]]:
    """path → {line in the NEW file: text} for every `+` line, from the hunk headers. `positions`, when given, is
    filled with path → {line of the DIFF TEXT: line in the new file} — a critic handed the raw diff may count
    the diff's own lines; the judge accepts both coordinates."""
    out: dict[str, dict[int, str]] = {}
    path, new_no = None, 0
    for i, raw in enumerate(diff.splitlines(), 1):
        if raw.startswith("+++ "):
            path = raw[4:].strip()
            path = path[2:] if path.startswith("b/") else path
            out.setdefault(path, {})
            if positions is not None:
                positions.setdefault(path, {})
            continue
        m = re.match(r"^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@", raw)
        if m:
            new_no = int(m.group(1))
            continue
        if path is None or raw.startswith("---") or raw.startswith("diff "):
            continue
        if raw.startswith("+"):
            out[path][new_no] = raw[1:]
            if positions is not None:
                positions[path][i] = new_no
            new_no += 1
        elif raw.startswith("-"):
            continue
        elif raw.startswith(" ") or raw == "":
            new_no += 1
    return out


def consistency(repo: Path | None = None) -> list[str]:
    """The fixture holds its own promises: every anchor is an added line, the planted credential carries its marker and
    is invisible at rest, the two coordinate spaces never overlap and the tolerance reaches no two planted defects of
    one lens at once (both against the project's tolerance when a repo is at hand), and — with a repo — every lens's
    agent is in the roster. The judge refuses a fixture that breaks a promise: a false green is never a verdict."""
    problems: list[str] = []
    try:
        diff = fixture()
    except Exception as e:   # noqa: BLE001 — a fixture that does not decode is the finding
        return [f"the fixture does not decode: {e}"]
    added = added_lines(diff)
    for lens, items in EXPECTED.items():
        for it in items:
            for f, n in it["at"]:
                if n not in added.get(f, {}):
                    problems.append(f"{lens}/{it['id']}: anchor {f}:{n} is not an added line of the fixture")
    secret = [n for n, t in added.get("src/orders/repo.py", {}).items() if "canary-secret" in t and "BILLING" in t]
    if not secret:
        problems.append("the planted credential's own line does not carry the `canary-secret` marker")
    at_rest = Path(__file__).read_text(encoding="utf-8", errors="replace")
    planted = next((t for t in added.get("src/orders/repo.py", {}).values() if "canary-secret" in t), "")
    value = planted.split('"')[1] if planted.count('"') >= 2 else ""
    if not value or value in at_rest:   # the credential's value itself, never spelled in this file
        problems.append("the planted credential is visible at rest (or absent) — the fixture must stay encoded in this file")
    # the two coordinate spaces never overlap: a critic may number the diff text or the new file; the filler that leads
    # the diff keeps every anchored file's diff-text lines far above every anchor, so neither reading lands on another anchor
    positions: dict[str, dict[int, int]] = {}
    added_lines(diff, positions)
    anchored = {f for items in EXPECTED.values() for it in items for f, _ in it["at"]}
    lowest_diff_line = min((d for f in anchored for d in positions.get(f, {})), default=0)
    highest_anchor = max(n for items in EXPECTED.values() for it in items for _, n in it["at"])
    highest_new_line = max((n for f in anchored for n in added.get(f, {})), default=0)   # a new-file reading that equals a diff-text line would be remapped: the bound is the longest anchored file, not the highest anchor
    bound = max(highest_anchor, highest_new_line)
    tol = DEFAULT_TOLERANCE
    if repo is not None:
        try:
            tol = tolerance(repo)
        except GateFault as e:
            problems.append(_home(str(e)))
    if lowest_diff_line <= bound + tol:
        problems.append(f"the diff text's lines of the anchored files start at {lowest_diff_line}, within reach of the new file's numbering (to {bound}, tolerance to {bound + tol}) — lead the diff with a longer filler or lower agents.canary.line_tolerance")
    # the tolerance reaches no two planted defects of one lens at once: one finding between two anchors of the same file
    # would credit both (a shared anchor — the same coordinate under two items — is on purpose and not a pair)
    for lens, items in EXPECTED.items():
        for i, a in enumerate(items):
            for b in items[i + 1:]:
                for f, n in a["at"]:
                    for f2, n2 in b["at"]:
                        if f == f2 and n != n2 and 2 * tol >= abs(n - n2):
                            problems.append(f"rules/agents.md: agents.canary.line_tolerance {tol} reaches two planted defects of the {lens} lens at once ({f}: {n} and {n2} are {abs(n - n2)} apart) — keep it under {abs(n - n2) / 2:g}")
    if repo is not None:
        from . import agents as agents_mod
        try:
            names = {r.get("name") for r in agents_mod.policy(repo)["roster"] if isinstance(r, dict)}   # the reader holds the roster to a list
            for lens, agent in LENS_AGENT.items():
                if agent not in names:
                    problems.append(f"rules/agents.md: lens {lens}: its agent {agent} is not in the roster")
        except GateFault as e:
            problems.append(_home(str(e)))
    return list(dict.fromkeys(problems))   # a problem said once (a policy that cannot be read fails the tolerance and the roster alike)


def _home(fault: str) -> str:
    """A policy fault filed where it comes from: the config file it names, the rule otherwise."""
    m = re.search(r"config/[\w.-]+\.json", fault)
    return (m.group(0) + ": " if m else "rules/agents.md: ") + fault


def tolerance(repo: Path) -> int:
    from . import agents as agents_mod   # the one policy home
    pol = agents_mod.policy(repo)
    c = pol.get("canary") if isinstance(pol.get("canary"), dict) else None
    v = c.get("line_tolerance") if c else None
    if isinstance(v, bool) or not isinstance(v, int) or v < 0:
        raise GateFault("agents.canary.line_tolerance must be a non-negative integer in rules/agents.md — the canary's match window is a key (EVOL-059)")
    return v


def findings(text: str) -> list[tuple[str, int, str]]:
    """The contract's own finding shape (agents.FINDING) — one definition; a line outside it is not a finding here either."""
    from . import agents as agents_mod
    out = []
    for line in text.splitlines():
        m = agents_mod.FINDING.match(line)
        if m:
            f, n = m.group("loc").rsplit(":", 1)
            f = f[2:] if f.startswith(("./", "a/", "b/")) else f
            out.append((f, int(n), m.group("sev")))
    return out


def _record_path(repo: Path) -> Path:
    return repo / STATE_DIR / RECORD


def read_record(repo: Path) -> dict:
    p = _record_path(repo)
    if not p.is_file():
        return {"judged": {}, "seen": {}}
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"the canary record {p.relative_to(repo)} is unreadable ({e}) — delete it and judge the lenses again") from None
    shaped = (isinstance(d, dict) and isinstance(d.get("judged", {}), dict) and isinstance(d.get("seen", {}), dict)
              and all(isinstance(v, dict) for v in d.get("judged", {}).values()) and all(isinstance(v, dict) for v in d.get("seen", {}).values()))
    if not shaped:
        raise GateFault(f"the canary record {p.relative_to(repo)} is not the record's shape (judged, seen: a mapping per lens) — delete it and judge the lenses again")
    d.setdefault("judged", {}); d.setdefault("seen", {})
    return d


def _write_record(repo: Path, d: dict) -> None:
    p = _record_path(repo)
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_suffix(".tmp")
    tmp.write_text(json.dumps(d, indent=0, sort_keys=True), encoding="utf-8")
    tmp.replace(p)


def _now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _lens(lens: str) -> str:
    if lens not in EXPECTED:
        raise GateFault(f"lens `{lens}` is not one of {', '.join(LENSES)}")
    return lens


def judge(repo: Path, lens: str, text: str, model: str) -> dict:
    """Compare a critic's return over the fixture to the lens's planted defects; record; red when any was missed."""
    lens = _lens(lens)
    model = (model or "").strip()
    if not model:
        raise GateFault("--judge needs --model: the id the critic's return carries on its `Model:` line (the harness states it; `unknown` when it does not)")
    tol = tolerance(repo)
    broken = consistency(repo)
    if broken:
        raise GateFault("the fixture is inconsistent under this project's policy — a verdict here could be a false green; `gate.py canary --check` names it: " + broken[0])
    positions: dict[str, dict[int, int]] = {}
    added_lines(fixture(), positions)
    from . import agents as agents_mod
    all_findings = findings(text)
    if not all_findings and not agents_mod.NO_FINDINGS.search(text or ""):   # the contract's one regex (agents --check-return reads the same)
        raise GateFault("the return carries no finding in the contract shape and no `no findings` line — hold it to the contract (gate.py agents --check-return) before judging; a formatting fault is not model drift")
    def _key(f: str) -> str:   # the fixture's own path for the one the critic wrote: exact, or by its tail (an absolute or prefixed path still names the file)
        return f if f in positions else next((p for p in positions if f.endswith("/" + p)), f)   # exact first, then the tail
    got = [(_key(f), {n, positions.get(_key(f), {}).get(n, n)}) for f, n, sev in all_findings if sev in SEVERITY_ABOVE_INFO]   # one finding, both readings: the new file's line, or the diff text's mapped to it
    found, missed = [], []
    for it in EXPECTED[lens]:
        hit = any(f == af and any(abs(x - an) <= tol for x in ns) for f, ns in got for af, an in it["at"])
        (found if hit else missed).append(it["id"])
    d = read_record(repo)
    d["judged"][lens] = {"model": model, "at": _now(), "found": found, "missed": missed}
    _write_record(repo, d)
    return {"ok": not missed, "lens": lens, "model": model, "found": found, "missed": missed, "tolerance": tol,
            "findings": len(got), "reason": ("every planted defect found" if not missed else
                                             "missed: " + ", ".join(f"{m} ({next(i['what'] for i in EXPECTED[lens] if i['id'] == m)})" for m in missed))}


def seen(repo: Path, lens: str, model: str) -> dict:
    lens = _lens(lens)
    model = (model or "").strip() or "unknown"
    d = read_record(repo)
    d["seen"][lens] = {"model": model, "at": _now()}
    _write_record(repo, d)
    return {"ok": True, "lens": lens, "model": model}


def plan(repo: Path, all_: bool = False) -> dict:
    """The lenses owed a canary. One definition: on a fixture the judge would refuse, nothing is owed and the fault is
    named (`fault`) — the spawn reader and both spawn sites read this, never a second reading."""
    d = read_record(repo)
    broken = consistency(repo)
    owed, lenses = [], {}
    for lens in LENSES:
        j, s = d["judged"].get(lens) or {}, d["seen"].get(lens) or {}
        judged, current = j.get("model"), s.get("model")
        if all_:
            why = "on demand"
        elif not judged:
            why = "never judged"
        elif current and current != judged:
            why = f"the model moved: judged on `{judged}`, last ran on `{current}`"
        elif current == "unknown" or judged == "unknown":
            why = "the model is unknown (the return carried no id) — judged until it is known"
        else:
            why = ""
        lenses[lens] = {"agent": LENS_AGENT[lens], "judged_on": judged, "last_ran_on": current, "missed": j.get("missed"), "reason": why or "judged on the model it last ran on"}
        if why and not broken:
            owed.append(lens)
    out = {"owed": owed, "lenses": lenses, "fixture_ok": not broken}
    if broken:
        out["fault"] = "the fixture is inconsistent under this project's policy — no lens is owed until the fault is cured; gate.py canary --check names it: " + broken[0]
    return out


def render_plan(r: dict) -> str:
    head = ("FAULT — nothing owed until the fault below is cured" if r.get("fault") else
            "owed — " + ", ".join(r["owed"]) if r["owed"] else "nothing owed — every lens judged on the model it last ran on")
    lines = [f"canary: {head}"]
    for lens, v in r["lenses"].items():
        lines.append(f"  {'→' if lens in r['owed'] else '·'} {lens} ({v['agent']}): judged on {v['judged_on'] or '—'} · last ran on {v['last_ran_on'] or '—'}"
                     + (f" · missed {', '.join(v['missed'])}" if v.get("missed") else "") + f" — {v['reason']}")
    if r.get("fault"):
        lines.append("  ✗ " + r["fault"])
    if r["owed"]:
        lines.append("  run: for each owed lens — gate.py agents --resolve --class work-critic, the fixture (gate.py canary --fixture) as the diff, the return "
                     "check, then gate.py canary --judge --lens <lens> --model <the return's Model: line>; post the verdict on the tracking item; a red canary opens the spawn policy's review by RDR")
    return "\n".join(lines)


def render_judge(r: dict) -> str:
    return (f"canary: {'ok' if r['ok'] else 'RED'} — {r['lens']} on {r['model']}: found {', '.join(r['found']) or 'none'}; "
            f"{r['reason']} ({r['findings']} finding(s) above informational read, ±{r['tolerance']} lines)"
            + ("" if r["ok"] else "\n  a red canary never blocks the train: it opens the review of the spawn policy (rules/agents.md → families, ladder, resolve rows) by RDR with the user"))
